  final int viewCount;
  final DateTime? publishedDate;
  final String? tags;
  final bool isOfficial;
  final bool isDownloadable;
  final int durationMinutes;
  final int pageCount;
  final String? thumbnailUrl;
  final String? sourceUrl;
  final String language;
  final DateTime? verifiedAt;
