    return RoadmapTasksCompanion(
      taskId: Value(taskId),
      dayId: Value(dayId),
      userId: Value(userId),
      topicId: topicId == null && nullToAbsent
          ? const Value.absent()
          : Value(topicId),
      title: Value(title),
      kind: Value(kind),
      estimatedMinutes: Value(estimatedMinutes),
      status: Value(status),
      orderIndex: Value(orderIndex),
      completedAt: completedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(completedAt),
    );
