class $$SubjectsTableTableManager
    extends
        RootTableManager<
          _$PrepNodeDatabase,
          $SubjectsTable,
          Subject,
          $$SubjectsTableFilterComposer,
          $$SubjectsTableOrderingComposer,
          $$SubjectsTableAnnotationComposer,
          $$SubjectsTableCreateCompanionBuilder,
          $$SubjectsTableUpdateCompanionBuilder,
          (Subject, $$SubjectsTableReferences),
          Subject,
          PrefetchHooks Function({
            bool examId,
            bool topicsRefs,
            bool questionsRefs,
            bool mockTestsRefs,
          })
        > {
  $$SubjectsTableTableManager(_$PrepNodeDatabase db, $SubjectsTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$SubjectsTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$SubjectsTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$SubjectsTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> subjectId = const Value.absent(),
                Value<String> examId = const Value.absent(),
                Value<String> subjectName = const Value.absent(),
                Value<double> importanceWeight = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => SubjectsCompanion(
                subjectId: subjectId,
                examId: examId,
                subjectName: subjectName,
                importanceWeight: importanceWeight,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String subjectId,
                required String examId,
                required String subjectName,
                Value<double> importanceWeight = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => SubjectsCompanion.insert(
                subjectId: subjectId,
                examId: examId,
                subjectName: subjectName,
                importanceWeight: importanceWeight,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable(table),
                  $$SubjectsTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                examId = false,
                topicsRefs = false,
                questionsRefs = false,
                mockTestsRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (topicsRefs) db.topics,
                    if (questionsRefs) db.questions,
                    if (mockTestsRefs) db.mockTests,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (examId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.examId,
                                    referencedTable: $$SubjectsTableReferences
                                        ._examIdTable(db),
                                    referencedColumn: $$SubjectsTableReferences
                                        ._examIdTable(db)
                                        .examId,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (topicsRefs)
                        await $_getPrefetchedData<
                          Subject,
                          $SubjectsTable,
                          Topic
                        >(
                          currentTable: table,
                          referencedTable: $$SubjectsTableReferences
                              ._topicsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$SubjectsTableReferences(
                                db,
                                table,
                                p0,
                              ).topicsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.subjectId == item.subjectId,
                              ),
                          typedResults: items,
                        ),
                      if (questionsRefs)
                        await $_getPrefetchedData<
                          Subject,
                          $SubjectsTable,
                          Question
                        >(
                          currentTable: table,
                          referencedTable: $$SubjectsTableReferences
                              ._questionsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$SubjectsTableReferences(
                                db,
                                table,
                                p0,
                              ).questionsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.subjectId == item.subjectId,
                              ),
                          typedResults: items,
                        ),
                      if (mockTestsRefs)
                        await $_getPrefetchedData<
                          Subject,
                          $SubjectsTable,
                          MockTest
                        >(
                          currentTable: table,
                          referencedTable: $$SubjectsTableReferences
                              ._mockTestsRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$SubjectsTableReferences(
                                db,
                                table,
                                p0,
                              ).mockTestsRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.subjectId == item.subjectId,
                              ),
                          typedResults: items,
                        ),
                    ];
                  },
                );
              },
        ),
      );
}

